package com.ecopulse.model; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; @Entity @Table(name="consumption_records") public class ConsumptionRecord { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="organization_id",nullable=false) public Long organizationId; @Column(name="building_id",nullable=false) public Long buildingId; @Column(name="recorded_at",nullable=false) public Instant recordedAt; @Column(name="electricity_kwh",nullable=false) public BigDecimal electricityKwh=BigDecimal.ZERO; @Column(name="water_liters",nullable=false) public BigDecimal waterLiters=BigDecimal.ZERO; @Column(name="waste_kg",nullable=false) public BigDecimal wasteKg=BigDecimal.ZERO; @Column(name="cost_inr",nullable=false) public BigDecimal costInr=BigDecimal.ZERO; @Column(name="co2_kg",nullable=false) public BigDecimal co2Kg=BigDecimal.ZERO; @Column(nullable=false) public String source="MANUAL"; @Column(name="import_key",nullable=false,unique=true) public String importKey; }
